var i=`0837-dal-makhani`;var n=`world-0837`;var t=`IN`;var s=`south-asia`;var r=4;var o=696;var l={en:`Dal Makhani`,ua:`Дал макхані`};var g={en:`Dal Makhani is a India dish made with urad dal, kidney beans, tomato passata, ginger-garlic paste. This home-scale recipe assigns measured ingredients to the steps where they are used.`,ua:`Дал макхані, страва кухні країни Індія. Основні складники: урід дал, червона квасоля кідні, томатна пасата, імбирно-часникова паста. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів.`};var d=[{en:`Soak the listed rice, grains or noodles in clean water for about 480 minutes as appropriate, then drain; grind rice and urad for batter if required by this dish.`,ua:`Замочіть зазначені рис, крупи або локшину у чистій воді приблизно на 480 хвилин залежно від продукту, потім злийте; для тіста за потреби подрібніть рис і урад.`,t:[`soaking-legumes`],m:480,i:[[`urad-dal`,190,`g`],[`kidney-beans`,110,`g`],[`water`,950,`ml`]]},{en:`Discard the soaking water. Bring the kidney beans and whole urad to a rolling boil for at least ten minutes, then continue simmering until completely soft.`,ua:`Злийте воду від замочування. Інтенсивно кип’ятіть червону квасолю й цілий урад не менше десяти хвилин, потім варіть до повної м’якості.`,t:[`boiling`],m:85,i:[[`water`,1100,`ml`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 110 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 110 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:110,i:[[`tomato-passata`,280,`g`],[`ginger-garlic-paste`,22,`g`],[`ground-cumin`,5,`g`],[`ground-turmeric`,3,`g`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:18,i:[[`unsalted-butter`,65,`g`],[`heavy-cream`,135,`ml`],[`garam-masala`,5,`g`],[`table-salt`,null,`to_taste`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`cilantro`,15,`g`]]}];var m={slug:i,id:n,country:`IN`,region:s,servings:4,minutes:696,title:l,text:g,steps:d};export{t as country,m as default,n as id,o as minutes,s as region,r as servings,i as slug,d as steps,g as text,l as title};